{"content": "def evaluate(store, task, profile, compute):
    # Check owner permission before any operations
    if task['owner'] != profile['owner']:
        raise PermissionError("Owner mismatch")

    # If task version doesn't match profile version, return None without side effects
    if task['version'] != profile['version']:
        return None

    # Create cache key including owner, profile.version, criteria_version, job_text
    key = (task['owner'], profile['version'], task['criteria_version'], task['job_text'])

    # Check if result is already cached
    if key not in store:
        # Call compute and cache the result
        try:
            result = compute()
            store[key] = result
        except Exception:
            # If compute raises an exception, propagate it without caching
            raise
    else:
        # Return cached result
        result = store[key]

    return result"}
